:root {
  color-scheme: dark;
}

html, body {
  margin: 0;
  height: 100%;
  background: #020617;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.main {
  min-height: 100vh;
  background: #020617;
  color: #e5e7eb;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  place-items: center;
  padding: 24px;
}

.card {
  width: 100%;
  max-width: 420px;
  background: #020617;
  border-radius: 16px;
  border: 1px solid #1f2937;
  min-width: 0;
  padding: 18px 18px 16px;
  display: grid;
  gap: 16px;
}

.header {
  display: grid;
  gap: 4px;
}

.title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
}

.subtitle {
  margin: 0;
  font-size: 13px;
  color: #9ca3af;
}

.label {
  font-size: 13px;
  color: #9ca3af;
}

.dates {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.field {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.field--inline {
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
}

.field input,
.field select {
  min-width: 0;
  width: 100%;
  box-sizing: border-box;
  border-radius: 10px;
  border: 1px solid #374151;
  background: #0b1220;
  color: #e5e7eb;
  padding: 8px 10px;
  font: inherit;
  font-size: 14px;
}

.guests {
  margin: 0;
  padding: 10px 12px 12px;
  border: 1px solid #1f2937;
  border-radius: 12px;
  display: grid;
  gap: 8px;
}

.counter {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto auto;
  align-items: center;
  gap: 10px;
}

.counter-name {
  font-size: 14px;
}

.step {
  width: 32px;
  height: 32px;
  border-radius: 999px;
  border: 1px solid #4b5563;
  background: transparent;
  color: #e5e7eb;
  font-size: 16px;
  cursor: pointer;
}

.step:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.adults-count,
.children-count {
  min-width: 18px;
  text-align: center;
  font-variant-numeric: tabular-nums;
}

.hint,
.date-error,
.availability {
  margin: 0;
  font-size: 13px;
}

.hint {
  color: #9ca3af;
}

.date-error {
  color: #fca5a5;
}

.availability {
  color: #fcd34d;
}

.breakdown {
  margin: 0;
  display: grid;
  gap: 6px;
}

.line {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 14px;
}

.line dt,
.line dd {
  margin: 0;
}

.line dd {
  font-variant-numeric: tabular-nums;
}

.line--total {
  padding-top: 8px;
  border-top: 1px solid #1f2937;
  font-weight: 700;
}

.book,
.confirm,
.cancel {
  border-radius: 10px;
  font: inherit;
  font-size: 14px;
  font-weight: 600;
  padding: 10px 14px;
  cursor: pointer;
}

.book,
.confirm {
  border: 1px solid #f43f5e;
  background: #e11d48;
  color: #fff;
}

.book:disabled {
  border-color: #374151;
  background: #1f2937;
  color: #6b7280;
  cursor: not-allowed;
}

.cancel {
  border: 1px solid #4b5563;
  background: transparent;
  color: #e5e7eb;
}

.booked-message {
  margin: 0;
  font-size: 14px;
  color: #86efac;
}

.backdrop {
  position: fixed;
  inset: 0;
  background: rgba(2, 6, 23, 0.72);
  display: grid;
  place-items: center;
  padding: 16px;
}

.confirm-dialog {
  width: 100%;
  max-width: 360px;
  box-sizing: border-box;
  border-radius: 14px;
  border: 1px solid #374151;
  background: #0b1220;
  padding: 16px;
  display: grid;
  gap: 12px;
}

.dialog-title {
  margin: 0;
  font-size: 17px;
}

.confirm-summary {
  margin: 0;
  font-size: 14px;
  color: #d1d5db;
  overflow-wrap: anywhere;
}

.dialog-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

button:focus-visible,
input:focus-visible,
select:focus-visible,
.booked-message:focus-visible {
  outline: 2px solid #60a5fa;
  outline-offset: 2px;
}
